Lemma combine_seq_sel : forall {X} (F : X -> X) (l : list X) (n : nat) (i : Z) (d : X),
  map (fun ir : Z * X => if fst ir =? i then F (snd ir) else snd ir) (combine (map Z.of_nat (seq n (length l))) l)
  = if i <? Z.of_nat n then l else upd l (Z.to_nat (i - Z.of_nat n)) (F (nth (Z.to_nat (i - Z.of_nat n)) l d)).
Proof.
