Lemma Forall2_upd_nth : forall {A B} (P Q : A -> B -> Prop) l l' i b',
  Forall2 P l l' ->
  (forall k a b, k <> i -> nth_error l k = Some a -> nth_error l' k = Some b -> P a b -> Q a b) ->
  (forall a b, nth_error l i = Some a -> nth_error l' i = Some b -> P a b -> Q a b') ->
